CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('ADMIN','TECH','USER')));
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id SERIAL PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,category_id INT NOT NULL REFERENCES categories(id),priority VARCHAR(10) NOT NULL CHECK(priority IN ('BAJA','MEDIA','ALTA','CRITICA')),status VARCHAR(20) NOT NULL DEFAULT 'NUEVO' CHECK(status IN ('NUEVO','ASIGNADO','EN_PROCESO','RESUELTO','CERRADO')),reporter_id INT NOT NULL REFERENCES users(id),technician_id INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS incident_history(id SERIAL PRIMARY KEY,incident_id INT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,user_id INT NOT NULL REFERENCES users(id),action VARCHAR(30) NOT NULL,detail TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
